  ('8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'previdenciario', 'Previdenciário (benefício por incapacidade)',
insert into public.secoes (id, tipo_laudo_id, codigo, titulo, ordem, condicional, condicao, texto_automatico_template) values
  ('56c1ada8-c415-5109-923a-28f4ba40609f', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'identificacao_perito', 'I — Identificação do(a) Perito(a) Judicial', 1, false, null, null),
  ('ca537439-1ffa-5cad-9c44-a370f3817ed7', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'identificacao_periciando', 'II — Identificação do(a) Periciando(a)', 2, false, null, null),
  ('00ac5dc1-0ac2-5279-a775-dd8a48ed4ad5', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'acompanhante_fontes_informacoes', 'III — Acompanhante e Fontes das Informações', 3, false, null, null),
  ('e4116d60-0f2f-5a86-9a29-1be1b6e52449', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'objeto_pericia', 'IV — Objeto da Perícia', 4, false, null, 'Sob a perspectiva médico-pericial, busca-se determinar a existência de doença ou lesão, sua repercussão funcional e eventual comprometimento da capacidade para o exercício da atividade habitual, estabelecendo-se, quando tecnicamente possível: diagnóstico médico-pericial; repercussão funcional; existência ou ausência de incapacidade; grau; duração; abrangência profissional; Data de Início da Doença (DID); Data de Início da Incapacidade (DII); eventual Data estimada de Cessação (DCB); capacidade laborativa residual; possibilidade de reabilitação profissional; necessidade de assistência permanente de terceiros; eventual sequela permanente com redução da capacidade; e nexo causal ou concausal, quando integrante do objeto da perícia.'),
  ('84d3ad27-3ca5-5aa5-bc67-a3ecc7e1396b', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'metodologia_pericial', 'V — Metodologia Pericial', 5, false, null, 'A conclusão resulta da integração entre documentação, anamnese, achados objetivos do exame, funcionalidade e exigências concretas da ocupação analisada.'),
  ('0a602c52-5658-54fe-ad0e-0aac1b66d759', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'matriz_documentos_analisados', 'VI — Matriz dos Documentos Analisados', 6, false, null, 'Para formação da conclusão médico-pericial foram analisados {{total_documentos}} documentos, totalizando {{total_paginas}} páginas, compreendendo {{categorias_principais}}, os quais foram confrontados com as informações obtidas durante a entrevista e com os achados objetivos da avaliação clínica.'),
  ('e33c1e48-b908-5520-85e9-50b217bc8351', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'situacao_historico_previdenciario', 'VII — Situação e Histórico Previdenciário', 7, false, null, null),
  ('992ce38d-b2a8-5046-96a8-cffc205f7763', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'historico_ocupacional_atividade_habitual', 'VIII — Histórico Ocupacional e Análise da Atividade Habitual', 8, false, null, 'A atividade habitual de {{funcao_efetivamente_exercida}} demanda esforço predominantemente {{demanda_fisica}}, sendo exercida principalmente em {{postura_predominante}}, com necessidade de {{exigencias_ocupacionais}}. Tais características foram consideradas para a análise da compatibilidade entre as limitações médico-funcionais e o exercício profissional.'),
  ('a07014d0-33eb-56c9-9e4f-2071b423dce2', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'historia_clinica', 'IX — História Clínica', 9, false, null, null),
  ('c55cf12f-6bcc-5411-9bfc-d353c62dbd7d', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'antecedentes', 'X — Antecedentes', 10, false, null, null),
  ('bf620648-d102-5944-be23-857f3fca13df', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'observacao_pericial_espontanea', 'XI — Observação Pericial Espontânea', 11, false, null, null),
  ('847ebc03-07ff-5cb9-8d00-47b2bda70544', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'exame_clinico_geral', 'XII — Exame Clínico Geral', 12, false, null, null),
  ('c18f7582-0f81-5511-97f7-5c4566802e28', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'exame_fisico_aparelhos_sistemas', 'XIII — Exame Físico por Aparelhos e Sistemas', 13, false, null, null),
  ('78c8c2b5-daf5-5740-afe6-12c78e6294e5', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'avaliacao_funcional_global', 'XIV — Avaliação Funcional Global', 14, false, null, null),
  ('a66ceb5a-70bf-5d34-8496-56b659168971', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'correlacao_medico_funcional_atividade_laboral', 'XV — Correlação Médico-Funcional com a Atividade Laboral', 15, false, null, 'O(a) periciando(a) apresenta {{diagnostico_informado}}, com achados objetivos caracterizados por {{achados_objetivos_exame}}. Tais alterações determinam {{repercussao_funcional_objetiva}} de limitação para {{funcoes_afetadas}}, as quais se mostram {{compatibilidade_atividade}} com as exigências da atividade habitual de {{profissao_habitual}}.'),
  ('281c7fe3-d8ed-52d8-b7d6-ad7c4fef4322', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'analise_incapacidade_laborativa', 'XVI — Análise da Incapacidade Laborativa', 16, false, null, null),
  ('01aa25a0-c846-59b4-865e-afdc8d24e7da', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'datas_tecnicas', 'XVII — Datas Técnicas', 17, false, null, null),
  ('cf06b38a-c4d1-5ea1-9618-3961dda2b365', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'capacidade_residual_reabilitacao', 'XVIII — Capacidade Residual e Reabilitação', 18, false, null, null),
  ('c6fbccc2-2bf4-5ace-9f70-ba7b1e349584', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'necessidade_assistencia_permanente_terceiros', 'XIX — Necessidade de Assistência Permanente de Terceiros', 19, false, null, null),
  ('114ff044-8db3-5021-9d87-8a4bbdf256ce', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'sequela_acidente_reducao_capacidade', 'XX — Sequela de Acidente / Redução da Capacidade', 20, false, null, null),
  ('9e58c7b3-2a22-57fa-9025-7f191512a365', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'nexo', 'XXI — Nexo — Quando Pertinente', 21, false, null, null),
  ('0aae5abb-eb2b-52c6-ac0b-37ab20773d3e', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'isencao_carencia', 'XXII — Isenção de Carência — Quando Pertinente', 22, false, null, 'A identificação médica da condição não substitui a análise dos demais requisitos jurídicos e previdenciários.'),
  ('59e3d96a-0477-5aa0-90f3-824a366f44cb', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'discussao_medico_pericial', 'XXIII — Discussão Médico-Pericial', 23, false, null, 'A existência de doença ou diagnóstico médico não caracteriza, isoladamente, incapacidade laborativa. No presente caso, o(a) periciando(a) apresenta {{diagnostico_informado}} ({{cid_informado}}), cuja existência encontra-se {{condicao_objetivamente_demonstrada}} pelos elementos documentais e clínicos analisados. Ao exame pericial foram identificados {{achados_objetivos_exame}}, determinando limitações relacionadas a {{funcoes_comprometidas}}. A atividade habitual de {{profissao_habitual}} demanda {{exigencias_ocupacionais}}. Da correlação entre os achados clínicos, a repercussão funcional e as exigências da atividade, verifica-se {{compatibilidade_atividade}} entre o estado de saúde atual e o exercício da ocupação habitual. Quando presente incapacidade, esta se caracteriza como {{grau_incapacidade}}, {{duracao_incapacidade}} e {{abrangencia_profissional}}, com capacidade residual {{capacidade_residual}} e possibilidade de reabilitação {{reabilitacao_profissional_indicacao}}.'),
  ('1f302925-40f6-5297-a215-75d33244a96d', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'respostas_quesitos', 'XXIV — Respostas aos Quesitos', 24, false, null, null),
  ('e097358b-4963-5cb9-8151-3aa285914a6b', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'conclusao_medico_pericial', 'XXV — Conclusão Médico-Pericial', 25, false, null, null),
  ('91ce41a8-487f-5b10-8987-aeec69272873', '8519bfb1-f7e8-5afc-8990-c82f62f207a1', 'encerramento', 'XXVI — Encerramento', 26, false, null, 'O presente laudo representa o entendimento técnico deste(a) Médico(a) Perito(a) Judicial, fundamentado nos elementos documentais disponíveis, informações colhidas durante a entrevista, exame clínico realizado pessoalmente, avaliação funcional e correlação dos achados com as exigências da atividade laborativa objeto da perícia. Permanecendo à disposição deste Juízo para eventuais esclarecimentos que se façam necessários. {{cidade_uf_assinatura}}, {{data_assinatura}}. Dr(a). {{nome_perito}}, Médico(a) Perito(a) Judicial, CRM/{{crm_uf}}, RQE nº {{rqe}}. Documento assinado eletronicamente.');
