  ('7e20f8d8-1b6b-5571-9737-2950a3042100', 'e097358b-4963-5cb9-8151-3aa285914a6b', null, 'conclusao_necessita_assistencia_terceiros', 'Necessita assistência permanente de terceiros', 'selecao_unica', 13, false, true, '[{"codigo": "nao", "rotulo": "Não"}, {"codigo": "sim", "rotulo": "Sim"}]'::jsonb, null, false, null, false, null),
  ('3986431a-9253-5e56-9c22-38c90e11ebf4', 'e097358b-4963-5cb9-8151-3aa285914a6b', null, 'conclusao_sequela_reducao_permanente', 'Sequela com redução permanente da capacidade', 'selecao_unica', 14, false, true, '[{"codigo": "nao", "rotulo": "Não"}, {"codigo": "sim", "rotulo": "Sim"}, {"codigo": "nao_aplicavel", "rotulo": "Não aplicável"}]'::jsonb, null, false, null, false, null),
  ('ec4bb767-df1e-5eff-996e-61f2dcc1f9dc', 'e097358b-4963-5cb9-8151-3aa285914a6b', null, 'conclusao_modelo_automatico', 'Modelo automático de conclusão', 'selecao_unica', 15, false, true, '[{"codigo": "capacidade_preservada", "rotulo": "Capacidade preservada", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, contudo os achados clínicos objetivos e as repercussões funcionais identificadas na presente avaliação não demonstram limitação de magnitude suficiente para impedir o exercício da atividade habitual de {{profissao_habitual}}. Sob a perspectiva médico-pericial, encontra-se preservada a capacidade laborativa na data do exame."}, {"codigo": "incapacidade_temporaria", "rotulo": "Incapacidade temporária", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, associado a {{achados_objetivos_exame}}, determinando limitações funcionais incompatíveis, no momento, com as exigências da atividade habitual de {{profissao_habitual}}. Caracteriza-se incapacidade laborativa {{conclusao_grau_incapacidade}}, de natureza temporária, com DII estabelecida em {{conclusao_dii}} e recuperação estimada para {{data_periodo_recuperacao_estimada}}, condicionada à evolução clínica e terapêutica."}, {"codigo": "incapacidade_permanente_com_reabilitacao", "rotulo": "Incapacidade permanente com reabilitação", "texto_automatico": "O conjunto dos achados médico-periciais demonstra limitação funcional permanente incompatível com o retorno à atividade habitual de {{profissao_habitual}}. Entretanto, encontram-se preservadas capacidades funcionais que permitem considerar viável a reabilitação profissional para atividade compatível com as restrições identificadas."}, {"codigo": "incapacidade_permanente_sem_reabilitacao", "rotulo": "Incapacidade permanente sem possibilidade de reabilitação", "texto_automatico": "O conjunto dos achados clínicos e funcionais evidencia comprometimento de caráter permanente e extensão suficiente para inviabilizar o desempenho da atividade habitual e de outras atividades compatíveis capazes de garantir subsistência, não se identificando, sob a perspectiva médico-funcional atual, potencial razoável de reabilitação profissional."}, {"codigo": "reducao_permanente_capacidade", "rotulo": "Redução permanente da capacidade", "texto_automatico": "O(a) periciando(a) apresenta sequela consolidada decorrente de {{evento_causador_sequela}}, determinando redução permanente da capacidade para o desempenho da atividade habitualmente exercida, embora permaneça apto(a) ao trabalho mediante maior esforço, adaptação ou redução funcional correspondente às limitações descritas."}]'::jsonb, null, false, null, true, null),
